<?php
use App\Core\Router; use App\Controllers\{AuthController,DashboardController,CrudController,DrawController,LedgerController,InstallController};
$r=new Router();$r->get('/install',[InstallController::class,'index']);$r->get('/login',[AuthController::class,'loginForm']);$r->post('/login',[AuthController::class,'login']);$r->get('/logout',[AuthController::class,'logout']);$r->get('/forgot-password',[AuthController::class,'forgot']);$r->get('/',[DashboardController::class,'index']);$r->get('/draws',[DrawController::class,'index']);$r->post('/draws/run',[DrawController::class,'run']);$r->get('/ledger',[LedgerController::class,'index']);$r->post('/ledger',[LedgerController::class,'store']);$r->get('/admin/{table}',[CrudController::class,'index']);$r->post('/admin/{table}',[CrudController::class,'store']);$r->post('/admin/{table}/{id}/delete',[CrudController::class,'delete']);return $r;
